import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const h=JSON.parse('{"title":"Заказы, контракты и общие цели","description":"","frontmatter":{"pageId":"players/procurement","contentRevision":5},"headers":[],"relativePath":"ru/players/procurement.md","filePath":"ru/players/procurement.md"}'),l={name:"ru/players/procurement.md"};function n(s,e,i,p,d,m){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="заказы-контракты-и-общие-цели" tabindex="-1">Заказы, контракты и общие цели <a class="header-anchor" href="#заказы-контракты-и-общие-цели" aria-label="Permalink to &quot;Заказы, контракты и общие цели&quot;">​</a></h1><p>Применимость: Rimlink 0.9.2 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p><strong>Заказ на закупку:</strong> укажи defName, количество и цену за единицу. Сервер резервирует цену × количество; поставщики выполняют части и сразу получают оплату.</p><p><strong>Адресный контракт:</strong> предложение видно выбранному поставщику, который приносит весь запрошенный объём за один раз.</p><p><strong>Общая цель:</strong> участники вносят ресурсы в эскроу до полного набора. Затем награда распределяется пропорционально вкладу; целочисленный остаток разбирается по возрастанию supplierId, после чего применяется комиссия. Отмена возвращает ресурсы участникам и деньги организатору.</p><p>Перед подтверждением проверь остаток и срок: избыточная поставка не делится автоматически.</p><h2 id="procurement-steps" tabindex="-1">Как создать заказ и поставить ресурс? <a class="header-anchor" href="#procurement-steps" aria-label="Permalink to &quot;Как создать заказ и поставить ресурс? {#procurement-steps}&quot;">​</a></h2><p>Консоль связи → экономика → <strong>«Закупки»</strong>. Организатор выбирает режим, технический defName (например Steel), количество, цену единицы/фонд и срок. Посмотри показанный резерв и подтверди: серебро должно уже быть на кошельке.</p><p>Поставщик открывает доступную карточку, обновляет остаток, выбирает предметы под маяками и проверяет итог. Для закупки можно поставить часть остатка; для контракта — только весь объём и только назначенным поставщиком. Сверхквота отвергается <strong>целиком</strong>, сервер не разрезает непрозрачный блоб автоматически.</p><p>После принятия обычной закупки ресурс идёт организатору почтой, поставщик сразу получает оплату за вычетом комиссии. Проверяй чистую выплату, состав поставки и историю участия. Другие публичные изменения требуют кнопки «Обновить»; неизвестный ответ блокирует новые мутации, пока «Повторить запрос» не разрешит исходное намерение.</p><h2 id="goal-example" tabindex="-1">Общая цель: когда платят и как делится остаток? <a class="header-anchor" href="#goal-example" aria-label="Permalink to &quot;Общая цель: когда платят и как делится остаток? {#goal-example}&quot;">​</a></h2><p>Пример без комиссии: квота 3 Steel, фонд 10; А поставил 1, Б — 2. Целые доли равны 3 и 6, остаётся 1 серебро. Оно достаётся поставщику с меньшим ID: результат 4/6 либо 3/7. После этого применяется рыночная комиссия. До полной квоты ни ресурсы организатору, ни фонд поставщикам не выдаются.</p><p>Если незавершённую цель отменить или дождаться срока, поставщики получают свои вещи обратно, организатор — фонд. Это не частичный бесплатный подарок. Хранение портящихся вкладов может создать долг поставщика при обычном завершении/отмене; административная отмена и reset/archive освобождают такой возврат от платы за удержание. Финальная поставка проверяет freeze ранних участников, поэтому 100% на карточке не следует «исправлять» ручной раздачей.</p><p>Контракт учитывает только defName и количество: обещание «именно отличная стальная деталь» интерфейсом не гарантируется. Пешек и доказательства убийств NPC эти режимы не принимают.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Только defName и количество: без фильтра качества, материала, прочности и пешек. До 1 000 000 единиц, 720 часов, 1 000 000 000 серебра, 100 поставок; открытых заказов не больше min(20, MaxLotsPerPlayer). Заморозка прошлых поставщиков может остановить завершение цели.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./economy">Кошелёк, почта и рынок</a></li><li><a href="./../admins/administration">Панель и модерация</a></li></ul>',19)])])}const u=a(l,[["render",n]]);export{h as __pageData,u as default};
